import { saveAs } from 'file-saver'
import type { Chart } from 'chart.js'

/** Download a raster PNG on a white background, then restore the chart theme.
 * Publication vector figures are generated by scripts/make_publication_figure.py.
 */
export function exportChartAsPNG(chart: Chart, filename: string): void {
  if (!chart || !chart.canvas) {
    console.error('Invalid chart instance provided to exportChartAsPNG')
    return
  }

  const canvas = chart.canvas
  const ctx = canvas.getContext('2d')

  if (!ctx) {
    console.error('Could not get canvas context')
    return
  }

  // Store original theme settings
  const originalOptions = chart.config.options ?? {}

  try {
    // Apply light theme for better print quality
    const lightThemeOptions = {
      ...originalOptions,
      plugins: {
        ...originalOptions.plugins,
        legend: {
          ...originalOptions.plugins?.legend,
          labels: {
            ...originalOptions.plugins?.legend?.labels,
            color: '#1f2937', // Dark gray for text
          },
        },
        title: {
          ...originalOptions.plugins?.title,
          color: '#1f2937',
        },
        tooltip: {
          ...originalOptions.plugins?.tooltip,
          backgroundColor: 'rgba(255, 255, 255, 0.95)',
          titleColor: '#111827',
          bodyColor: '#374151',
          borderColor: '#d1d5db',
        },
      },
      scales: originalOptions.scales ? {
        ...originalOptions.scales,
        x: originalOptions.scales?.x ? {
          ...originalOptions.scales.x,
          ticks: {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            ...(originalOptions.scales.x as any)?.ticks,
            color: '#6b7280',
          },
          grid: {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            ...(originalOptions.scales.x as any)?.grid,
            color: 'rgba(209, 213, 219, 0.5)',
          },
          border: {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            ...(originalOptions.scales.x as any)?.border,
            color: '#d1d5db',
          },
        } : undefined,
        y: originalOptions.scales?.y ? {
          ...originalOptions.scales.y,
          ticks: {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            ...(originalOptions.scales.y as any)?.ticks,
            color: '#6b7280',
          },
          grid: {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            ...(originalOptions.scales.y as any)?.grid,
            color: 'rgba(209, 213, 219, 0.5)',
          },
          border: {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            ...(originalOptions.scales.y as any)?.border,
            color: '#d1d5db',
          },
        } : undefined,
      } : undefined,
    }

    // Update chart with light theme
    chart.options = lightThemeOptions
    chart.update('none') // Update without animation

    // update('none') renders synchronously; capture before another export can start.
    // Composite onto white; a PNG must not masquerade as a vector SVG.
    const exportCanvas = document.createElement('canvas')
    exportCanvas.width = canvas.width
    exportCanvas.height = canvas.height
    const exportContext = exportCanvas.getContext('2d')
    if (!exportContext) throw new Error('Could not create export canvas')
    exportContext.fillStyle = '#ffffff'
    exportContext.fillRect(0, 0, canvas.width, canvas.height)
    exportContext.drawImage(canvas, 0, 0)
    const dataUrl = exportCanvas.toDataURL('image/png')
    const encoded = dataUrl.split(',')[1]
    if (!encoded) throw new Error('Could not encode PNG')
    const bytes = Uint8Array.from(atob(encoded), character => character.charCodeAt(0))
    const blob = new Blob([bytes], { type: 'image/png' })
    const pngFilename = `${filename.replace(/\.(?:png|svg)$/i, '')}.png`
    saveAs(blob, pngFilename)

  } catch (error) {
    console.error('Error exporting chart as PNG:', error)

  } finally {
    // Restore raw config options, never a resolved Chart.js options proxy.
    chart.options = originalOptions
    chart.update('none')
  }
}

export default exportChartAsPNG
